import os
import glob

results = {}

# ===== 任务1: 检查 SVG 文件目录 =====
svg_dir = r"F:\files\marching-route-data\symbol"
results["task1_svg_dir"] = {"path": svg_dir, "exists": os.path.isdir(svg_dir)}
if os.path.isdir(svg_dir):
    svg_files = glob.glob(os.path.join(svg_dir, "*.svg"))
    results["task1_svg_dir"]["svg_files"] = [os.path.basename(f) for f in sorted(svg_files)]
    results["task1_svg_dir"]["count"] = len(svg_files)
else:
    results["task1_svg_dir"]["svg_files"] = []
    results["task1_svg_dir"]["count"] = 0

# ===== 任务2: 在 autocarto 下搜索 CombinedMilitaryPlot =====
autocarto_dir = r"F:\PythonProjects\Eino\autocarto"
results["task2_autocarto_search"] = {"path": autocarto_dir, "exists": os.path.isdir(autocarto_dir)}
if os.path.isdir(autocarto_dir):
    found_dirs = []
    for root, dirs, files in os.walk(autocarto_dir):
        for d in dirs:
            if "combinedmilitaryplot" in d.lower().replace("_",""):
                found_dirs.append(os.path.join(root, d))
        # 也检查文件名
        for f in files:
            if "combinedmilitaryplot" in f.lower().replace("_",""):
                found_dirs.append(os.path.join(root, f))
    results["task2_autocarto_search"]["found_items"] = found_dirs
else:
    results["task2_autocarto_search"]["found_items"] = []

# ===== 任务3: 在 F:\ 下搜索 CombinedMilitaryPlot =====
search_root = r"F:\"
results["task3_drive_F_search"] = {"path": search_root, "exists": os.path.isdir(search_root)}
if os.path.isdir(search_root):
    found_items = []
    # 只搜索深度为3以内，避免太慢
    search_terms = ["combinedmilitaryplot", "CombinedMilitaryPlot", "militaryplot"]
    for item_name in os.listdir(search_root):
        item_lower = item_name.lower().replace("_","").replace("-","")
        if any(term in item_lower for term in ["combinedmilitary", "militaryplot"]):
            found_items.append(os.path.join(search_root, item_name))
        # 深入一级
        item_path = os.path.join(search_root, item_name)
        if os.path.isdir(item_path):
            try:
                for sub_name in os.listdir(item_path):
                    sub_lower = sub_name.lower().replace("_","").replace("-","")
                    if any(term in sub_lower for term in ["combinedmilitary", "militaryplot"]):
                        found_items.append(os.path.join(item_path, sub_name))
            except:
                pass
    results["task3_drive_F_search"]["found_items"] = found_items
else:
    results["task3_drive_F_search"]["found_items"] = []

# ===== 任务4: 检查QGIS默认插件目录 =====
# QGIS插件目录常见位置
qgis_plugin_candidates = [
    os.path.expanduser(r"~\AppData\Roaming\QGIS\QGIS3\profiles\default\python\plugins"),
    os.path.expanduser(r"~\AppData\Roaming\QGIS\QGIS3\profiles\default\plugins"),
    os.path.expanduser(r"~\.qgis2\python\plugins"),
    os.path.expanduser(r"~\.qgis3\python\plugins"),
    r"C:\Program Files\QGIS 3.xx\apps\qgis\python\plugins",
    r"C:\Program Files\QGIS\apps\qgis\python\plugins",
    r"C:\OSGeo4W\apps\qgis\python\plugins",
    r"C:\OSGeo4W64\apps\qgis\python\plugins",
]

results["task4_qgis_plugins"] = {"candidates_checked": []}
for plugin_dir in qgis_plugin_candidates:
    info = {"path": plugin_dir, "exists": os.path.isdir(plugin_dir)}
    if os.path.isdir(plugin_dir):
        # 列出所有子目录找CombinedMilitaryPlot
        subdirs = [d for d in os.listdir(plugin_dir) if os.path.isdir(os.path.join(plugin_dir, d))]
        info["all_plugins"] = subdirs
        cmp_items = [d for d in subdirs if "combinedmilitary" in d.lower().replace("_","") or "militaryplot" in d.lower().replace("_","")]
        info["combined_military_plot"] = cmp_items
    results["task4_qgis_plugins"]["candidates_checked"].append(info)

# 另外使用 QGIS 的 API 查找
try:
    from qgis.core import QgsApplication
    plugin_path = QgsApplication.pluginPath()
    results["task4_qgis_plugins_qgis_api"] = {"plugin_path": plugin_path, "exists": os.path.isdir(plugin_path)}
    if os.path.isdir(plugin_path):
        subdirs = [d for d in os.listdir(plugin_path) if os.path.isdir(os.path.join(plugin_path, d))]
        results["task4_qgis_plugins_qgis_api"]["all_plugins"] = subdirs
        cmp_items = [d for d in subdirs if "combinedmilitary" in d.lower().replace("_","") or "militaryplot" in d.lower().replace("_","")]
        results["task4_qgis_plugins_qgis_api"]["combined_military_plot"] = cmp_items

    # 同时获取用户插件路径
    user_plugin_path = QgsApplication.qgisSettingsDir() + r"python\plugins"
    results["task4_qgis_user_plugins"] = {"path": user_plugin_path, "exists": os.path.isdir(user_plugin_path)}
    if os.path.isdir(user_plugin_path):
        subdirs = [d for d in os.listdir(user_plugin_path) if os.path.isdir(os.path.join(user_plugin_path, d))]
        results["task4_qgis_user_plugins"]["all_plugins"] = subdirs
        cmp_items = [d for d in subdirs if "combinedmilitary" in d.lower().replace("_","") or "militaryplot" in d.lower().replace("_","")]
        results["task4_qgis_user_plugins"]["combined_military_plot"] = cmp_items
except Exception as e:
    results["task4_qgis_api_error"] = str(e)

# 输出结果
