from pathlib import Path
import json

results = {}

# 任务1: SVG目录
svg_dir = Path("F:/files/marching-route-data/symbol")
results["task1_svg_dir"] = {"path": str(svg_dir), "exists": svg_dir.is_dir()}
if svg_dir.is_dir():
    svg_files = sorted([str(f.name) for f in svg_dir.glob("*.svg")])
    results["task1_svg_dir"]["svg_files"] = svg_files
    results["task1_svg_dir"]["count"] = len(svg_files)
else:
    results["task1_svg_dir"]["svg_files"] = []
    results["task1_svg_dir"]["count"] = 0

# 任务2: autocarto下搜索
adir = Path("F:/PythonProjects/Eino/autocarto")
results["task2_autocarto"] = {"path": str(adir), "exists": adir.is_dir()}
if adir.is_dir():
    found = []
    for p in adir.rglob("*"):
        if p.is_dir() or p.is_file():
            name_lower = p.name.lower().replace("_","").replace("-","")
            if "combinedmilitary" in name_lower or "militaryplot" in name_lower:
                found.append(str(p))
    results["task2_autocarto"]["found_items"] = found
else:
    results["task2_autocarto"]["found_items"] = []

# 任务3: F盘搜索（深度2级）
f_root = Path("F:/")
results["task3_drive_f"] = {"path": str(f_root), "exists": f_root.is_dir()}
found_f = []
if f_root.is_dir():
    try:
        for p1 in f_root.iterdir():
            n1l = p1.name.lower().replace("_","").replace("-","")
            if "combinedmilitary" in n1l or "militaryplot" in n1l:
                found_f.append(str(p1))
            if p1.is_dir():
                try:
                    for p2 in p1.iterdir():
                        n2l = p2.name.lower().replace("_","").replace("-","")
                        if "combinedmilitary" in n2l or "militaryplot" in n2l:
                            found_f.append(str(p2))
                except:
                    pass
    except:
        pass
results["task3_drive_f"]["found_items"] = found_f

# 任务4: QGIS插件目录
home = Path.home()
plugins_candidates = [
    home / "AppData/Roaming/QGIS/QGIS3/profiles/default/python/plugins",
    home / "AppData/Roaming/QGIS/QGIS3/profiles/default/plugins",
    home / ".qgis2/python/plugins",
    home / ".qgis3/python/plugins",
    Path("C:/Program Files/QGIS 3.xx/apps/qgis/python/plugins"),
    Path("C:/Program Files/QGIS/apps/qgis/python/plugins"),
    Path("C:/OSGeo4W/apps/qgis/python/plugins"),
    Path("C:/OSGeo4W64/apps/qgis/python/plugins")
]
results["task4_plugins"] = []
for pd in plugins_candidates:
    info = {"path": str(pd), "exists": pd.is_dir()}
    if pd.is_dir():
        try:
            subdirs = sorted([d.name for d in pd.iterdir() if d.is_dir()])
            info["plugins"] = subdirs
            cmp = [d for d in subdirs if "combinedmilitary" in d.lower().replace("_","") or "militaryplot" in d.lower().replace("_","")]
            info["combined_military_plot_found"] = cmp
        except:
            info["plugins"] = []
            info["combined_military_plot_found"] = []
    results["task4_plugins"].append(info)

# QGIS API
try:
    from qgis.core import QgsApplication
    pp = QgsApplication.pluginPath()
    pp_path = Path(pp)
    info_api = {"path": str(pp_path), "exists": pp_path.is_dir()}
    if pp_path.is_dir():
        subdirs = sorted([d.name for d in pp_path.iterdir() if d.is_dir()])
        info_api["plugins"] = subdirs
        cmp = [d for d in subdirs if "combinedmilitary" in d.lower().replace("_","") or "militaryplot" in d.lower().replace("_","")]
        info_api["combined_military_plot_found"] = cmp
    results["task4_qgis_api_pluginpath"] = info_api

    settings_dir = QgsApplication.qgisSettingsDir()
    up_path = Path(settings_dir) / "python/plugins"
    info_user = {"path": str(up_path), "exists": up_path.is_dir()}
    if up_path.is_dir():
        subdirs = sorted([d.name for d in up_path.iterdir() if d.is_dir()])
        info_user["plugins"] = subdirs
        cmp = [d for d in subdirs if "combinedmilitary" in d.lower().replace("_","") or "militaryplot" in d.lower().replace("_","")]
        info_user["combined_military_plot_found"] = cmp
    results["task4_qgis_user_plugins"] = info_user

    # Profile base
    profile_path = up_path.parent.parent
    results["task4_profile_base"] = {"path": str(profile_path), "exists": profile_path.is_dir()}
except Exception as e:
    results["task4_api_error"] = str(e)

print(json.dumps(results, indent=2, ensure_ascii=False))
